window.SECTIONS = window.SECTIONS || [];
window.SECTIONS.push({
  "slug": "ergo-atraktou",
  "num": "4.4α",
  "title": "Έργο και ισχύς ατράκτου",
  "kicker": "Ενέργεια που περιστρέφεται",
  "lead": "Πώς μεταφέρεται ενέργεια με περιστρεφόμενους άξονες, όπως στο βαρούλκο, στην έλικα ενός πλοίου ή στους τροχούς ενός αυτοκινήτου.",
  "blocks": [
    {
      "type": "p",
      "text": "Στη μηχανολογία η ενέργεια μεταφέρεται πολύ συχνά με ατράκτους, δηλαδή άξονες που περιστρέφονται: στο βαρούλκο που ανεβάζει έναν κουβά, στην έλικα μιας βάρκας, στους τροχούς ενός αυτοκινήτου. Εδώ το σημείο εφαρμογής της δύναμης κινείται σε κύκλο."
    },
    {
      "type": "callout",
      "kind": "def",
      "text": "Ροπή \\( M \\) μιας δύναμης ως προς έναν άξονα είναι το γινόμενο της δύναμης επί την απόσταση του σημείου εφαρμογής της από τον άξονα: \\( M = F \\cdot r \\). Μετριέται σε N · m."
    },
    {
      "type": "p",
      "text": "Ας υπολογίσουμε το έργο μιας δύναμης \\( F \\) που εφαρμόζεται εφαπτομενικά σε απόσταση \\( r \\) από τον άξονα (π.χ. στη μανιβέλα ενός βαρούλκου). Σε μία πλήρη στροφή, το σημείο εφαρμογής διανύει μήκος κύκλου \\( \\ell = 2\\pi r \\). Άρα το έργο σε μία στροφή είναι:"
    },
    {
      "type": "formula",
      "html": "\\[ W_{1} = F \\cdot 2\\pi r = 2\\pi\\,(F\\,r) = 2\\pi\\,M \\]"
    },
    {
      "type": "p",
      "text": "Αν ο άξονας κάνει \\( \\nu \\) στροφές, το έργο πολλαπλασιάζεται επί \\( \\nu \\):"
    },
    {
      "type": "formula",
      "html": "\\[ W = 2\\pi\\,\\nu\\,M \\]",
      "caption": "\\( \\nu \\): αριθμός στροφών (καθαρός αριθμός) · \\( M \\) σε N · m · \\( W \\) σε J"
    },
    {
      "type": "h",
      "text": "Η ισχύς της ατράκτου"
    },
    {
      "type": "callout",
      "kind": "def",
      "text": "Ισχύς \\( \\dot{W} \\) είναι το έργο που μεταφέρεται στη μονάδα του χρόνου: \\( \\dot{W} = W / t \\). Μετριέται σε watt, \\( 1\\ \\text{W} = 1\\ \\text{J/s} \\). Η τελεία πάνω από το \\( W \\) δείχνει «ανά μονάδα χρόνου»."
    },
    {
      "type": "p",
      "text": "Για μια άτρακτο που περιστρέφεται με \\( n \\) στροφές ανά δευτερόλεπτο, σε χρόνο \\( t \\) κάνει \\( \\nu = n\\,t \\) στροφές. Διαιρώντας το έργο με τον χρόνο:"
    },
    {
      "type": "formula",
      "html": "\\[ \\dot{W} = \\frac{2\\pi\\,\\nu\\,M}{t} = 2\\pi\\,n\\,M \\]",
      "caption": "\\( n \\) σε στροφές ανά δευτερόλεπτο · \\( M \\) σε N · m · \\( \\dot{W} \\) σε W"
    },
    {
      "type": "callout",
      "kind": "remember",
      "text": "Οι κινητήρες δίνουν τις στροφές σε σ.α.λ. (στροφές ανά λεπτό). Πριν εφαρμόσεις τον τύπο, μετατρέπεις: \\( n = \\dfrac{\\text{σ.α.λ.}}{60} \\) στροφές ανά δευτερόλεπτο. Αν ξεχάσεις τη διαίρεση με το 60, το αποτέλεσμα βγαίνει 60 φορές μεγαλύτερο."
    },
    {
      "type": "callout",
      "kind": "example",
      "title": "Παράδειγμα 4.4",
      "text": "Να υπολογίσεις την ισχύ που μεταφέρεται μέσω της ατράκτου ενός αυτοκινήτου, όταν η ροπή που εφαρμόζεται στην άτρακτο είναι \\( 300\\ \\text{N} \\cdot \\text{m} \\) και περιστρέφεται με \\( 3000 \\) σ.α.λ."
    },
    {
      "type": "p",
      "text": "Λύση: πρώτα μετατρέπουμε τις στροφές σε στροφές ανά δευτερόλεπτο:"
    },
    {
      "type": "formula",
      "html": "\\[ n = \\frac{3000}{60} = 50\\ \\text{στροφές/s} \\]"
    },
    {
      "type": "formula",
      "html": "\\[ \\dot{W} = 2\\pi\\,n\\,M = 2\\pi \\cdot 50 \\cdot 300\\ \\text{N}\\cdot\\text{m/s} \\approx 94\\,248\\ \\text{W} \\approx 94{,}2\\ \\text{kW} \\]"
    },
    {
      "type": "h",
      "text": "Για εξάσκηση"
    },
    {
      "type": "p",
      "text": "Άσκηση 3. Ένας ιμάντας κινεί μια τροχαλία διαμέτρου \\( 40\\ \\text{cm} \\), που περιστρέφεται με \\( 500 \\) σ.α.λ. Η κινητήρια δύναμη που ασκεί ο ιμάντας είναι \\( 300\\ \\text{N} \\). Να υπολογίσεις το έργο που παράγεται σε μία ώρα."
    },
    {
      "type": "p",
      "text": "Απάντηση: η ακτίνα είναι \\( r = 0{,}2\\ \\text{m} \\), άρα \\( M = F r = 300 \\cdot 0{,}2 = 60\\ \\text{N}\\cdot\\text{m} \\). Σε μία ώρα η τροχαλία κάνει \\( \\nu = 500 \\cdot 60 = 30\\,000 \\) στροφές. Άρα \\( W = 2\\pi\\,\\nu\\,M = 2\\pi \\cdot 30\\,000 \\cdot 60 \\approx 11\\,310\\,000\\ \\text{J} \\approx 11\\,310\\ \\text{kJ} \\), δηλαδή περίπου \\( 11{,}3\\ \\text{MJ} \\)."
    }
  ]
});
;

// --- Source: content/b/thermod/chapter-04/07-ergo-epitaxynsis.js ---
;
window.SECTIONS = window.SECTIONS || [];
window.SECTIONS.push({
  "slug": "ergo-epitaxynsis",
  "num": "4.4β",
  "title": "Έργο και ισχύς επιτάχυνσης",
  "kicker": "Από την ηρεμία στην κίνηση",
  "lead": "Πόσο έργο χρειάζεται για να αυξηθεί η ταχύτητα ενός σώματος.",
  "blocks": [
    {
      "type": "p",
      "text": "Όταν ένα σώμα μάζας \\( m \\) αλλάζει την ταχύτητά του από \\( c_1 \\) σε \\( c_2 \\) κατά τη διάρκεια μιας διαδρομής, το έργο που παράγεται ονομάζεται έργο επιτάχυνσης. Εδώ συμβολίζουμε την ταχύτητα με \\( c \\) (σε m/s), για να μην τη μπερδεύουμε με τον όγκο \\( V \\)."
    },
    {
      "type": "p",
      "text": "Θα βρούμε τον τύπο για σταθερή δύναμη, δηλαδή ομαλά επιταχυνόμενη κίνηση. Ξεκινάμε από τον τύπο \\( W = F \\ell \\) και από τον δεύτερο νόμο του Νεύτωνα \\( F = m a \\):"
    },
    {
      "type": "formula",
      "html": "\\[ W = F \\cdot \\ell, \\qquad F = m\\,a \\]"
    },
    {
      "type": "p",
      "text": "Στην ομαλά επιταχυνόμενη κίνηση, η επιτάχυνση και το διάστημα που διανύεται σε χρόνο \\( t \\) δίνονται από τις σχέσεις:"
    },
    {
      "type": "formula",
      "html": "\\[ a = \\frac{c_2 - c_1}{t}, \\qquad \\ell = \\frac{c_1 + c_2}{2}\\,t \\]",
      "caption": "Το διάστημα είναι η μέση ταχύτητα επί τον χρόνο"
    },
    {
      "type": "p",
      "text": "Αντικαθιστούμε. Ο χρόνος \\( t \\) απλοποιείται, και το γινόμενο \\( (c_2 - c_1)(c_2 + c_1) \\) ισούται με \\( c_2^2 - c_1^2 \\):"
    },
    {
      "type": "formula",
      "html": "\\[ W = m\\,\\frac{c_2 - c_1}{t} \\cdot \\frac{c_2 + c_1}{2}\\,t = \\tfrac{1}{2}\\,m\\,(c_2^{2} - c_1^{2}) \\]",
      "caption": "\\( m \\) σε kg, \\( c \\) σε m/s, \\( W \\) σε J"
    },
    {
      "type": "callout",
      "kind": "remember",
      "text": "Προσοχή: \\( c_2^2 - c_1^2 \\) δεν είναι ίσο με \\( (c_2 - c_1)^2 \\). Πρώτα υψώνεις κάθε ταχύτητα στο τετράγωνο και μετά αφαιρείς. Οι ταχύτητες μπαίνουν σε m/s: από km/h διαιρούμε με \\( 3{,}6 \\)."
    },
    {
      "type": "p",
      "text": "Η ισχύς επιτάχυνσης είναι το έργο επιτάχυνσης στη μονάδα του χρόνου, \\( \\dot{W} = W / t \\). Με αυτόν τον τύπο βρίσκουμε τη μέση ισχύ που απαιτείται κατά τη διάρκεια της επιτάχυνσης."
    },
    {
      "type": "callout",
      "kind": "example",
      "title": "Παράδειγμα 4.5",
      "text": "Να υπολογίσεις την ισχύ που απαιτείται για να επιταχύνει ένα όχημα μάζας \\( m = 2000\\ \\text{kg} \\), από την ηρεμία μέχρι να αποκτήσει ταχύτητα \\( 60\\ \\text{km/h} \\), σε χρόνο \\( 10\\ \\text{s} \\)."
    },
    {
      "type": "p",
      "text": "Λύση: το όχημα ξεκινά από την ηρεμία, άρα \\( c_1 = 0 \\). Μετατρέπουμε την τελική ταχύτητα σε m/s:"
    },
    {
      "type": "formula",
      "html": "\\[ c_2 = \\frac{60}{3{,}6} \\approx 16{,}67\\ \\text{m/s} \\]"
    },
    {
      "type": "formula",
      "html": "\\[ W = \\tfrac{1}{2}\\,m\\,(c_2^2 - c_1^2) = \\tfrac{1}{2} \\cdot 2000 \\cdot 16{,}67^2 \\approx 277\\,800\\ \\text{J} \\approx 277{,}8\\ \\text{kJ} \\]"
    },
    {
      "type": "formula",
      "html": "\\[ \\dot{W} = \\frac{W}{t} = \\frac{277{,}8\\ \\text{kJ}}{10\\ \\text{s}} \\approx 27{,}8\\ \\text{kW} \\]"
    }
  ]
});
;

// --- Source: content/b/thermod/chapter-04/08-ergo-ogkometavolis.js ---
;
window.SECTIONS = window.SECTIONS || [];
window.SECTIONS.push({
  "slug": "ergo-ogkometavolis",
  "num": "4.5",
  "title": "Έργο ογκομεταβολής (P·V)",
  "kicker": "Όταν ένα αέριο σπρώχνει το έμβολο",
  "lead": "Το έργο που παράγει ή απορροφά ένα αέριο όταν αλλάζει ο όγκος του.",
  "blocks": [
    {
      "type": "p",
      "text": "Σκέψου αέριο μέσα σε κύλινδρο με έμβολο. Όταν το αέριο διαστέλλεται, σπρώχνει το έμβολο και παράγει έργο. Το έργο αυτό ονομάζεται έργο ογκομεταβολής, γιατί συνδέεται με τη μεταβολή του όγκου του αερίου."
    },
    {
      "type": "p",
      "text": "Ας υποθέσουμε ότι η πίεση \\( P \\) του αερίου μένει σταθερή. Αν το έμβολο έχει εμβαδόν \\( A \\), η δύναμη στο έμβολο είναι \\( F = P\\,A \\). Αν το έμβολο μετακινηθεί κατά \\( \\ell \\), ο όγκος αυξάνεται κατά \\( \\Delta V = A\\,\\ell \\). Άρα:"
    },
    {
      "type": "formula",
      "html": "\\[ W = F\\,\\ell = P\\,A\\,\\ell = P\\,\\Delta V = P\\,(V_2 - V_1) \\]",
      "caption": "Για σταθερή πίεση · \\( P \\) σε Pa (N/m²), \\( V \\) σε m³, \\( W \\) σε J"
    },
    {
      "type": "p",
      "text": "Στο διάγραμμα \\( (P-V) \\) μια μεταβολή με σταθερή πίεση είναι οριζόντια ευθεία από την κατάσταση 1 στην κατάσταση 2. Το έργο είναι το εμβαδόν του ορθογωνίου κάτω από αυτή την ευθεία, με ύψος \\( P \\) και πλάτος \\( \\Delta V \\)."
    },
    {
      "type": "callout",
      "kind": "remember",
      "text": "Το πρόσημο ακολουθεί τη σύμβαση του 4.1: στη διαστολή \\( \\Delta V > 0 \\) και το έργο είναι θετικό (το αέριο παράγει έργο). Στη συμπίεση \\( \\Delta V < 0 \\) και το έργο είναι αρνητικό (προσφέρουμε έργο στο αέριο). Προσοχή στις μονάδες: \\( 1\\ \\text{kN/m}^2 = 1\\ \\text{kPa} = 1000\\ \\text{Pa} \\)."
    },
    {
      "type": "callout",
      "kind": "example",
      "title": "Παράδειγμα 4.6",
      "text": "Σε μια διάταξη κυλίνδρου–εμβόλου βρίσκεται αέριο υπό πίεση \\( 600\\ \\text{kN/m}^2 \\). Το αέριο διαστέλλεται με σταθερή πίεση από \\( 0{,}15\\ \\text{m}^3 \\) σε \\( 1{,}15\\ \\text{m}^3 \\). Να υπολογίσεις το παραγόμενο έργο."
    },
    {
      "type": "formula",
      "html": "\\[ W = P\\,(V_2 - V_1) = 600 \\cdot 10^{3}\\ \\frac{\\text{N}}{\\text{m}^2} \\cdot (1{,}15 - 0{,}15)\\ \\text{m}^3 = 6 \\cdot 10^{5}\\ \\text{N}\\cdot\\text{m} = 600\\ \\text{kJ} \\]",
      "caption": "Θετικό έργο: το αέριο διαστέλλεται και το παράγει"
    },
    {
      "type": "h",
      "text": "Για εξάσκηση"
    },
    {
      "type": "p",
      "text": "Άσκηση 6. Σε μια διάταξη κυλίνδρου–εμβόλου βρίσκεται αέριο υπό πίεση \\( 500\\ \\text{kN/m}^2 \\). Το αέριο διαστέλλεται με σταθερή πίεση από \\( 0,1\\ \\text{m}^3 \\) σε \\( 1,1\\ \\text{m}^3 \\). Να υπολογίσεις το παραγόμενο έργο."
    },
    {
      "type": "p",
      "text": "Απάντηση: \\( W = P\\,\\Delta V = 500 \\cdot 10^3 \\cdot (1,1 - 0,1) = 5 \\cdot 10^5\\ \\text{J} = 500\\ \\text{kJ} \\)."
    }
  ]
});
;

